SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "康福赴镇至方渠，击退出兵拦截的羌胡。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：康福行至方渠，羌胡出兵邀福，福击走之；；核对说明：本段未独纪日；承十月赴镇后，十一月段后排列不证明全部战事都十一月。羌胡是史书集称，无实名不补族首姓名。", "status": "draft", "id": "a1636628-acae-5091-a94d-0690a0a96349", "subject_id": "4dcfd8d7-fb7c-5726-bf9f-a3e87828ddde", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年赴镇途中；战事确月日未独载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：康福行至方渠，羌胡出兵邀福，福击走之；；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c50b7898-c97c-54b4-b4cd-d8bbaa9b120e", "subject_id": "4dcfd8d7-fb7c-5726-bf9f-a3e87828ddde", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记康福：赴镇遭拦、击退对方者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：康福行至方渠，羌胡出兵邀福，福击走之；；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "379db938-729f-5505-ac8d-bdb5ada53732", "subject_id": "7419fd99-6e0a-53d2-8c35-3a4c51f654d7", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "康福：赴镇遭拦、击退对方者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：康福行至方渠，羌胡出兵邀福，福击走之；；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "744c79f7-6460-59e6-acdd-d2cfbefabc94", "subject_id": "2dab814c-235e-5df0-8923-3492f21eda6d", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "event", "field_path": "description", "claim_text": "新康福传同记行至方渠，羌夷出邀，福击走之。", "citation": "《新五代史》卷四十六，段落 xin-wudaishi-b08f244b9241-p001748；EPUB电子本，纸本及异文待核", "note": "原文：行至方渠，而羌夷果出邀福，福以兵擊走之。；核对说明：同案互证，羌夷/羌胡称法保留，不定现代民族归属。", "status": "draft", "id": "8c286e80-a3de-59dc-b608-c84f152bdb25", "subject_id": "4dcfd8d7-fb7c-5726-bf9f-a3e87828ddde", "source_id": "fa846bdb-d3af-52fe-bd49-234d29dfd3cb"}, {"subject_table": "event", "field_path": "description", "claim_text": "康福至青刚峡，遣卫审𡷣突袭未觉唐兵到的吐蕃野利、大虫二族，主记大破、杀获殆尽。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：至青刚峡，遇吐蕃野利、大虫二族数千帐，皆不觉唐兵至，福遣卫审余掩击，大破之，杀获殆尽。；核对说明：数千帐是帐落不是精确人数；杀获是杀及俘合称，不写所有人均死。卫规范字沿上批校核、原摘录保留私用字；不与方渠拦截混成同一地战。", "status": "draft", "id": "47de1eb3-dbcd-508b-a4df-de099efe6d0b", "subject_id": "9f141796-e55d-5c6a-8d4a-963bdfadb02b", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年赴镇途中；战事确月日未独载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：至青刚峡，遇吐蕃野利、大虫二族数千帐，皆不觉唐兵至，福遣卫审余掩击，大破之，杀获殆尽。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c094cf07-41ae-5bd4-8339-8ee4989a8b94", "subject_id": "9f141796-e55d-5c6a-8d4a-963bdfadb02b", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "康福：命突袭者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：至青刚峡，遇吐蕃野利、大虫二族数千帐，皆不觉唐兵至，福遣卫审余掩击，大破之，杀获殆尽。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "14bef090-c01e-5f1f-8e2c-5e30eca9875a", "subject_id": "18191555-fb06-56f3-a362-c52f467d6ce1", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记卫审𡷣：奉命掩击者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：至青刚峡，遇吐蕃野利、大虫二族数千帐，皆不觉唐兵至，福遣卫审余掩击，大破之，杀获殆尽。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "99a5f0e7-15cc-57d6-a8b5-ecffec6a62a9", "subject_id": "86d5fe95-3599-59d1-9d35-8687182be4e7", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "卫审𡷣：奉命掩击者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：至青刚峡，遇吐蕃野利、大虫二族数千帐，皆不觉唐兵至，福遣卫审余掩击，大破之，杀获殆尽。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "9a62ce57-8ebb-57ec-9b89-99bf6e41b672", "subject_id": "870d9b8b-8670-5bec-a372-dd8bc974e500", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "event", "field_path": "description", "claim_text": "新康福传作青冈峡，记遇雪登山见烟火、分兵三道出其不意袭吐蕃，获玉璞绫锦羊马。", "citation": "《新五代史》卷四十六，段落 xin-wudaishi-b08f244b9241-p001748；EPUB电子本，纸本及异文待核", "note": "原文：至青岡峽，遇雪，福登山望見川谷中煙火，有吐蕃數千帳，不覺福至，福分其兵為三道，出其不意襲之。；核对说明：青刚/青冈地名异形保留；雪和三道为新补，不把数千帐改数千人；新后杀之殆尽更强于主杀获，未据此统一全死。", "status": "draft", "id": "9c05817b-3835-575d-a50e-f3c283ad311b", "subject_id": "9f141796-e55d-5c6a-8d4a-963bdfadb02b", "source_id": "fa846bdb-d3af-52fe-bd49-234d29dfd3cb"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧明宗纪十二月丁酉载康福奏破野利、大虫两族三百余帐于方渠、获牛羊三万。", "citation": "《旧五代史》卷四十，段落 jiu-wudaishi-205deb4a7860-p001173；EPUB电子本，纸本及异文待核", "note": "原文：十二月丁酉，靈武康福奏：「破野利、大蟲兩族三百餘帳於方渠，獲牛羊三萬。」；核对说明：同两族战报与主青刚峡数千帐在地点及帐数上有差，不用奏报时间差掩盖；并列待核，三万是牛羊不是俘兵。丁酉是奏报纪时，不倒作主战日。", "status": "draft", "id": "c63063c9-25b7-5a74-8d9a-a95938d79e77", "subject_id": "9f141796-e55d-5c6a-8d4a-963bdfadb02b", "source_id": "ff08029c-33a1-50f5-a21a-ddecc9e11683"}, {"subject_table": "event", "field_path": "description", "claim_text": "康福威声大振，进入灵州，主书记自此朔方始受朝廷派代。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：由是威声大振，遂进至灵州，自是朔方始受代。；核对说明：受代是军镇开始接受朝廷派代，不是改朝换代；威声为史述，未推全河西征服。", "status": "draft", "id": "bd9db983-805d-5ab7-8291-17c2952b58e5", "subject_id": "7d2cf6fd-92b0-5a11-ac09-76f9db8a91d1", "source_id": "b4a41ab1-5448-5cf5-8fef-ad8f161097a1"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年赴镇途中；战事确月日未独载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p033·原文件第119行", "note": "原文：由是威声大振，遂进至灵州，自是朔方始受代。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "329add63-cf64-58c6-873c-bcd27895a0c2", "subject_id": "7d2cf6fd-92b0-5a11-ac09-76f9db8a91d1", "s